from typing import Dict, List

def score_course(profile: Dict[str, float], course: Dict[str, float], w_interest=0.6, w_performance=0.4):
    interest = profile.get("interest", 0) * course.get("interest_fit", 0)
    performance = profile.get("performance", 0) * course.get("difficulty_fit", 0)
    return (interest * w_interest) + (performance * w_performance)

def rank_courses(profile: Dict[str, float], catalog: List[Dict[str, float]]):
    return sorted(catalog, key=lambda c: score_course(profile, c), reverse=True)

def confidence_from_profile(profile: dict) -> float:
    observed = sum(1 for v in profile.values() if v is not None)
    total = max(len(profile), 1)
    return observed / total

def adjusted_score(raw_score: float, confidence: float) -> float:
    return raw_score * (0.5 + 0.5 * confidence)
